import sys


def main():
    data = sys.stdin.read().split()
    n, c = int(data[0]), int(data[1])
    xs = sorted(map(int, data[2:2 + n]))
    lo, hi = 1, xs[-1] - xs[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        cnt, last = 1, xs[0]
        for x in xs:
            if x - last >= mid:
                cnt += 1
                last = x
                if cnt >= c:
                    break
        if cnt >= c:
            lo = mid
        else:
            hi = mid - 1
    print(lo)


